#!/usr/bin/env node
/**
 * context-preprocessor — converts Repomix XML output to structured minimal context
 * for small local models (qwen2.5-coder:1.5b has ~4k token context limit).
 *
 * Input:  Repomix XML file (generated by gen-context.mjs / npx repomix)
 * Output: Stripped, structured text ready for model consumption
 *
 * Usage:
 *   node context-preprocessor.mjs --input context.xml [options]
 *
 * Options:
 *   --input      Required. Path to Repomix XML file (within fabrica-saas/)
 *   --mode       files | symbols | summary | auto (default: auto)
 *   --max-chars  Max chars in output (default: 6000, model-safe for 1.5b)
 *   --output     Write to file instead of stdout
 *
 * Modes:
 *   files   — list file paths and line counts only
 *   symbols — extract exported functions/classes/consts per file
 *   summary — one-paragraph summary per file (first 200 chars)
 *   auto    — adaptive: symbols if JS/TS files, summary otherwise
 *
 * Exit codes: 0 = ok, 1 = error, 4 = invalid args
 */

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { resolve, dirname, extname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dir = dirname(fileURLToPath(import.meta.url));
const FACTORY_ROOT = resolve(__dir, '../../../');

// ─── XML parsing (no external deps) ───────────────────────────────────────

export function parseRepomixXml(xmlText) {
  const files = [];

  // Match <file> or <document> elements with path attribute
  const fileRe = /<(?:file|document)[^>]+path="([^"]+)"[^>]*>([\s\S]*?)<\/(?:file|document)>/g;
  let m;
  while ((m = fileRe.exec(xmlText)) !== null) {
    const path = m[1];
    const rawContent = m[2];
    // Strip inner XML tags (e.g. <content>, <![CDATA[...]]>)
    const content = rawContent
      .replace(/<!\[CDATA\[([\s\S]*?)]]>/g, '$1')
      .replace(/<[^>]+>/g, '')
      .trim();
    files.push({ path, content });
  }

  return files;
}

// ─── Extraction strategies ─────────────────────────────────────────────────

export function extractFiles(files) {
  const lines = ['=== FILES ==='];
  for (const f of files) {
    const lineCount = f.content.split('\n').length;
    lines.push(`${f.path} (${lineCount} lines)`);
  }
  return lines.join('\n');
}

export function extractSymbols(files) {
  const sections = ['=== SYMBOLS ==='];
  const exportRe = /^export\s+(?:default\s+)?(?:async\s+)?(?:function|class|const|let|var)\s+(\w+)/gm;
  const moduleExportRe = /^module\.exports\s*=\s*\{([^}]+)\}/m;

  for (const f of files) {
    const ext = extname(f.path);
    if (!['.js', '.mjs', '.jsx', '.ts', '.tsx'].includes(ext)) continue;

    const symbols = [];
    let match;
    exportRe.lastIndex = 0;
    while ((match = exportRe.exec(f.content)) !== null) {
      symbols.push(match[1]);
    }
    const cjsMatch = moduleExportRe.exec(f.content);
    if (cjsMatch) {
      const names = cjsMatch[1].split(',').map(s => s.trim().split(':')[0].trim()).filter(Boolean);
      symbols.push(...names);
    }

    if (symbols.length > 0) {
      sections.push(`\n${f.path}:\n  exports: ${symbols.join(', ')}`);
    }
  }
  return sections.join('\n');
}

export function extractSummary(files, charsPerFile = 200) {
  const sections = ['=== SUMMARY ==='];
  for (const f of files) {
    const preview = f.content.slice(0, charsPerFile).replace(/\n+/g, ' ').trim();
    sections.push(`\n${f.path}:\n  ${preview}`);
  }
  return sections.join('\n');
}

export function autoMode(files) {
  const jsFiles = files.filter(f => ['.js', '.mjs', '.jsx', '.ts', '.tsx'].includes(extname(f.path)));
  if (jsFiles.length > 0) {
    return extractSymbols(files);
  }
  return extractSummary(files);
}

export function applyMaxChars(text, maxChars) {
  if (text.length <= maxChars) return text;
  return text.slice(0, maxChars) + `\n[...truncated to ${maxChars} chars — use --max-chars to increase]`;
}

export function processRepomixXml(xmlText, mode = 'auto', maxChars = 6000) {
  const files = parseRepomixXml(xmlText);
  if (files.length === 0) {
    return `[context-preprocessor] No files found in XML input.\n` +
           `Input length: ${xmlText.length} chars. ` +
           `This may not be Repomix XML format.`;
  }

  let result;
  switch (mode) {
    case 'files':   result = extractFiles(files);   break;
    case 'symbols': result = extractSymbols(files); break;
    case 'summary': result = extractSummary(files); break;
    case 'auto':
    default:        result = autoMode(files);       break;
  }

  const header = `[context-preprocessor] ${files.length} files | mode=${mode} | before=${xmlText.length} chars\n\n`;
  return applyMaxChars(header + result, maxChars);
}

// ─── CLI entrypoint ────────────────────────────────────────────────────────

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const args = {};
  for (let i = 2; i < process.argv.length; i++) {
    const a = process.argv[i];
    if (a.startsWith('--')) {
      const key = a.slice(2);
      const next = process.argv[i + 1];
      if (!next || next.startsWith('--')) { args[key] = true; }
      else { args[key] = next; i++; }
    }
  }

  if (!args.input) {
    process.stderr.write('Error: --input is required\n');
    process.stderr.write('Usage: node context-preprocessor.mjs --input context.xml [--mode files|symbols|summary|auto]\n');
    process.exit(4);
  }

  const inputPath = resolve(process.cwd(), args.input);

  // Scope check: must be within fabrica-saas/
  if (!inputPath.startsWith(FACTORY_ROOT)) {
    process.stderr.write(`Error: input file must be within fabrica-saas/. Got: ${inputPath}\n`);
    process.exit(4);
  }
  if (!existsSync(inputPath)) {
    process.stderr.write(`Error: input file not found: ${inputPath}\n`);
    process.exit(1);
  }

  // Security: reject files containing secrets patterns
  const SECRETS_PATTERNS = ['.env', 'secret', 'credential', 'private_key', 'api_key', 'token'];
  const lowerInput = inputPath.toLowerCase();
  if (SECRETS_PATTERNS.some(p => lowerInput.includes(p) && !lowerInput.includes('.ai/context'))) {
    process.stderr.write(`Error: refusing to process potentially sensitive file: ${inputPath}\n`);
    process.exit(4);
  }

  const xmlText  = readFileSync(inputPath, 'utf-8');
  const mode     = args.mode ?? 'auto';
  const maxChars = parseInt(args['max-chars'] ?? '6000', 10);
  const result   = processRepomixXml(xmlText, mode, maxChars);

  if (args.output) {
    const outPath = resolve(process.cwd(), args.output);
    if (!outPath.startsWith(FACTORY_ROOT)) {
      process.stderr.write(`Error: output file must be within fabrica-saas/\n`);
      process.exit(4);
    }
    writeFileSync(outPath, result, 'utf-8');
    process.stderr.write(`[context-preprocessor] Written to ${outPath} (${result.length} chars)\n`);
  } else {
    process.stdout.write(result + '\n');
  }
}
